import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"21、【噬嗑】 震下离上","description":"温公易说 - 21、【噬嗑】 震下离上","frontmatter":{"title":"21、【噬嗑】 震下离上","description":"温公易说 - 21、【噬嗑】 震下离上"},"headers":[],"relativePath":"zh/classics/wengong/022.md","filePath":"zh/classics/wengong/022.md"}'),n={name:"zh/classics/wengong/022.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_21、【噬嗑】-震下离上" tabindex="-1">21、【噬嗑】 震下离上 <a class="header-anchor" href="#_21、【噬嗑】-震下离上" aria-label="Permalink to “21、【噬嗑】 震下离上”">​</a></h1><h3 id="彖曰-颐中有物曰噬嗑-噬嗑而亨。刚柔分-动而明-雷电合而章。柔得中而上行-虽不当位-利用狱也。" tabindex="-1">彖曰：颐中有物曰噬嗑，噬嗑而亨。刚柔分，动而明，雷电合而章。柔得中而上行，虽不当位，利用狱也。 <a class="header-anchor" href="#彖曰-颐中有物曰噬嗑-噬嗑而亨。刚柔分-动而明-雷电合而章。柔得中而上行-虽不当位-利用狱也。" aria-label="Permalink to “彖曰：颐中有物曰噬嗑，噬嗑而亨。刚柔分，动而明，雷电合而章。柔得中而上行，虽不当位，利用狱也。”">​</a></h3><h3 id="象曰-雷电噬嗑-先王以明罚勑法。" tabindex="-1">象曰：雷电噬嗑，先王以明罚勑法。 <a class="header-anchor" href="#象曰-雷电噬嗑-先王以明罚勑法。" aria-label="Permalink to “象曰：雷电噬嗑，先王以明罚勑法。”">​</a></h3><p>明罚勑法，先王明罚，非以残人，所以正法也。</p><h3 id="初九-屦校灭趾-无咎-象曰-屦校灭趾-不行也。" tabindex="-1">初九：屦校灭趾，无咎 象曰：屦校灭趾，不行也。 <a class="header-anchor" href="#初九-屦校灭趾-无咎-象曰-屦校灭趾-不行也。" aria-label="Permalink to “初九：屦校灭趾，无咎 象曰：屦校灭趾，不行也。”">​</a></h3><h3 id="六二-噬肤灭鼻-无咎-象曰-噬肤灭鼻-乘刚也。" tabindex="-1">六二：噬肤灭鼻，无咎 象曰：噬肤灭鼻，乘刚也。 <a class="header-anchor" href="#六二-噬肤灭鼻-无咎-象曰-噬肤灭鼻-乘刚也。" aria-label="Permalink to “六二：噬肤灭鼻，无咎 象曰：噬肤灭鼻，乘刚也。”">​</a></h3><h3 id="六三-噬腊肉-遇毒-小吝-无咎-象曰-遇毒-位不当也。" tabindex="-1">六三：噬腊肉，遇毒，小吝，无咎 象曰：遇毒，位不当也。 <a class="header-anchor" href="#六三-噬腊肉-遇毒-小吝-无咎-象曰-遇毒-位不当也。" aria-label="Permalink to “六三：噬腊肉，遇毒，小吝，无咎 象曰：遇毒，位不当也。”">​</a></h3><p>噬嗑，食也，故皆以食物明之。禽兽全干者谓之腊，噬之至难者也。干肉，噬肤而难于干胏者也。</p><h3 id="九四-噬干胏-得金矢-利艰贞-吉-象曰-利艰贞-吉-未光也。" tabindex="-1">九四：噬干胏，得金矢，利艰贞，吉 象曰：利艰贞，吉，未光也。 <a class="header-anchor" href="#九四-噬干胏-得金矢-利艰贞-吉-象曰-利艰贞-吉-未光也。" aria-label="Permalink to “九四：噬干胏，得金矢，利艰贞，吉 象曰：利艰贞，吉，未光也。”">​</a></h3><h3 id="六五-噬干肉-得黄金-贞厉-无咎-象曰-贞厉-无咎-得当也。" tabindex="-1">六五：噬干肉，得黄金，贞厉，无咎 象曰：贞厉，无咎，得当也。 <a class="header-anchor" href="#六五-噬干肉-得黄金-贞厉-无咎-象曰-贞厉-无咎-得当也。" aria-label="Permalink to “六五：噬干肉，得黄金，贞厉，无咎 象曰：贞厉，无咎，得当也。”">​</a></h3><h3 id="上九-何校灭耳-凶-象曰-何校灭耳-聪不明也。" tabindex="-1">上九：何校灭耳，凶 象曰：何校灭耳，聪不明也。 <a class="header-anchor" href="#上九-何校灭耳-凶-象曰-何校灭耳-聪不明也。" aria-label="Permalink to “上九：何校灭耳，凶 象曰：何校灭耳，聪不明也。”">​</a></h3>',11)])])}const f=e(n,[["render",l]]);export{b as __pageData,f as default};
